-- Converted: CREATE UNIQUE INDEX sales.ix_account_customer (customer_id) ON sales.account -> named UNIQUE constraint IX_ACCOUNT_CUSTOMER on SALES."ACCOUNT" (CUSTOMER_ID), without RELY.
-- Reason: Snowflake standard tables have no secondary indexes; the constraint keeps the key and its source name as metadata but is not enforced. RELY is left off because nothing guarantees CUSTOMER_ID is unique (the Teradata table is MULTISET and only the index enforced it), and RELY lets the optimizer eliminate joins on that assumption.
ALTER TABLE SALES."ACCOUNT" ADD CONSTRAINT IX_ACCOUNT_CUSTOMER UNIQUE (CUSTOMER_ID);

-- Converted: unique secondary index access path on CUSTOMER_ID -> search optimization for equality predicates on CUSTOMER_ID.
-- Reason: Search optimization is the Snowflake replacement for selective point lookups on standard tables; the single clustering key of SALES."ACCOUNT" is left for SALES.HIX_ACCOUNT.
ALTER TABLE SALES."ACCOUNT" ADD SEARCH OPTIMIZATION ON EQUALITY(CUSTOMER_ID);

-- Converted: CREATE PROCEDURE sales.add_payment(IN p_account BIGINT, IN p_amount DECIMAL(12, 2)) -> CREATE PROCEDURE SALES.ADD_PAYMENT(P_ACCOUNT NUMBER(19,0), P_AMOUNT NUMBER(12,2)) RETURNS VARCHAR LANGUAGE SQL with a $$-delimited Snowflake Scripting body.
-- Reason: Snowflake has no IN keyword (all arguments are input), requires a RETURNS clause (RETURN NULL stands in for no return value) and a delimited body; plain CREATE keeps the Teradata error when the procedure already exists.
-- Converted: SQL SECURITY OWNER -> EXECUTE AS OWNER; DYNAMIC RESULT SETS 1 -> removed.
-- Reason: Both run the body with the owner's privileges (snowflake.rule.procedure_execute_as); the body never opens a WITH RETURN cursor, so no result set is returned in either system.
CREATE PROCEDURE SALES.ADD_PAYMENT(P_ACCOUNT NUMBER(19,0), P_AMOUNT NUMBER(12,2))
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS
$$
DECLARE
    dup_count NUMBER(38,0) DEFAULT 0;
    duplicate_payment EXCEPTION (-20802, 'Duplicate row in SET table SALES.PAYMENT');
    duplicate_audit EXCEPTION (-20803, 'Duplicate row in SET table SALES.AUDIT_LOG (EVENT_ID 1, EVENT_TYPE PAYMENT)');
BEGIN
    -- Converted: Teradata SET-table duplicate-row error 2802 on SALES.PAYMENT -> NULL-safe existence check that raises -20802 before the insert.
    -- Reason: sales.payment is a SET table, so an identical (1, p_account, p_amount) row was rejected; EQUAL_NULL matches the duplicate-row rule where NULLs compare equal. Snowflake would accept the duplicate silently.
    SELECT COUNT(*) INTO :dup_count
    FROM SALES.PAYMENT p
    WHERE p.PAYMENT_ID = 1
      AND EQUAL_NULL(p.ACCOUNT_ID, :P_ACCOUNT)
      AND EQUAL_NULL(p.AMOUNT, :P_AMOUNT);
    IF (dup_count > 0) THEN
        RAISE duplicate_payment;
    END IF;

    -- Converted: INSERT INTO sales.payment ... VALUES (1, p_account, p_amount) -> same insert on SALES.PAYMENT with :P_ACCOUNT / :P_AMOUNT binds.
    -- Reason: Snowflake Scripting references arguments inside SQL with a colon prefix; the hard-coded PAYMENT_ID 1 is kept as in the source.
    INSERT INTO SALES.PAYMENT (PAYMENT_ID, ACCOUNT_ID, AMOUNT)
    VALUES (1, :P_ACCOUNT, :P_AMOUNT);

    -- Converted: Teradata SET-table duplicate-row error 2802 on SALES.AUDIT_LOG -> existence check that raises -20803.
    -- Reason: sales.audit_log is a SET table; EVENT_TYPE is NOT CASESPECIFIC in Teradata mode, so the comparison ignores case and trailing blanks. As in Teradata, the payment row stays committed when this check fails.
    SELECT COUNT(*) INTO :dup_count
    FROM SALES.AUDIT_LOG a
    WHERE a.EVENT_ID = 1
      AND UPPER(RTRIM(a.EVENT_TYPE)) = 'PAYMENT';
    IF (dup_count > 0) THEN
        RAISE duplicate_audit;
    END IF;

    -- Converted: INSERT INTO sales.audit_log ... VALUES (1, 'PAYMENT') -> same insert on SALES.AUDIT_LOG.
    -- Reason: Standard SQL insert; only the name changes per the naming map.
    INSERT INTO SALES.AUDIT_LOG (EVENT_ID, EVENT_TYPE)
    VALUES (1, 'PAYMENT');

    RETURN NULL;
END;
$$;

-- Converted: CREATE PROCEDURE sales.post_transfer(IN p_from BIGINT, IN p_to BIGINT, IN p_amount DECIMAL(12, 2)) -> CREATE PROCEDURE SALES.POST_TRANSFER(P_FROM NUMBER(19,0), P_TO NUMBER(19,0), P_AMOUNT NUMBER(12,2)) RETURNS VARCHAR LANGUAGE SQL with a $$-delimited Snowflake Scripting body.
-- Reason: Snowflake has no IN keyword, requires a RETURNS clause (RETURN NULL stands in for no return value) and a delimited body. P_AMOUNT is unused in the source body but kept so three-argument CALLs still resolve; plain CREATE keeps the Teradata error when the procedure already exists.
-- Converted: default SQL SECURITY (DEFINER) -> EXECUTE AS OWNER.
-- Reason: Closest Snowflake equivalent of definer's rights; Snowflake requires the clause to be explicit (snowflake.rule.procedure_execute_as).
CREATE PROCEDURE SALES.POST_TRANSFER(P_FROM NUMBER(19,0), P_TO NUMBER(19,0), P_AMOUNT NUMBER(12,2))
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS
$$
DECLARE
    dup_count NUMBER(38,0) DEFAULT 0;
    duplicate_transfer EXCEPTION (-20802, 'Duplicate row in SET table SALES.TRANSFER');
    duplicate_audit EXCEPTION (-20803, 'Duplicate row in SET table SALES.AUDIT_LOG (EVENT_ID 2, EVENT_TYPE TRANSFER)');
BEGIN
    -- Converted: Teradata SET-table duplicate-row error 2802 on SALES.TRANSFER -> NULL-safe existence check that raises -20802 before the insert.
    -- Reason: sales.transfer is a SET table, so an identical (1, p_from, p_to) row was rejected; EQUAL_NULL matches the duplicate-row rule where NULLs compare equal.
    SELECT COUNT(*) INTO :dup_count
    FROM SALES.TRANSFER t
    WHERE t.TRANSFER_ID = 1
      AND EQUAL_NULL(t.FROM_ACCOUNT, :P_FROM)
      AND EQUAL_NULL(t.TO_ACCOUNT, :P_TO);
    IF (dup_count > 0) THEN
        RAISE duplicate_transfer;
    END IF;

    -- Converted: INSERT INTO sales.transfer ... VALUES (1, p_from, p_to) -> same insert on SALES.TRANSFER with :P_FROM / :P_TO binds.
    -- Reason: Snowflake Scripting references arguments inside SQL with a colon prefix; the hard-coded TRANSFER_ID 1 is kept as in the source.
    INSERT INTO SALES.TRANSFER (TRANSFER_ID, FROM_ACCOUNT, TO_ACCOUNT)
    VALUES (1, :P_FROM, :P_TO);

    -- Converted: Teradata SET-table duplicate-row error 2802 on SALES.AUDIT_LOG -> existence check that raises -20803.
    -- Reason: sales.audit_log is a SET table; EVENT_TYPE is NOT CASESPECIFIC in Teradata mode, so the comparison ignores case and trailing blanks. As in Teradata, the transfer row stays committed when this check fails.
    SELECT COUNT(*) INTO :dup_count
    FROM SALES.AUDIT_LOG a
    WHERE a.EVENT_ID = 2
      AND UPPER(RTRIM(a.EVENT_TYPE)) = 'TRANSFER';
    IF (dup_count > 0) THEN
        RAISE duplicate_audit;
    END IF;

    -- Converted: INSERT INTO sales.audit_log ... VALUES (2, 'TRANSFER') -> same insert on SALES.AUDIT_LOG.
    -- Reason: Standard SQL insert; only the name changes per the naming map.
    INSERT INTO SALES.AUDIT_LOG (EVENT_ID, EVENT_TYPE)
    VALUES (2, 'TRANSFER');

    RETURN NULL;
END;
$$;

-- Converted: CREATE PROCEDURE sales.repair_payment() -> CREATE PROCEDURE SALES.REPAIR_PAYMENT() RETURNS VARCHAR LANGUAGE SQL with a $$-delimited Snowflake Scripting body.
-- Reason: Snowflake requires a RETURNS clause (RETURN NULL stands in for no return value) and a delimited body; plain CREATE keeps the Teradata error when the procedure already exists.
-- Converted: default SQL SECURITY (DEFINER) -> EXECUTE AS OWNER.
-- Reason: Closest Snowflake equivalent of definer's rights; Snowflake requires the clause to be explicit (snowflake.rule.procedure_execute_as).
CREATE PROCEDURE SALES.REPAIR_PAYMENT()
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS
$$
DECLARE
    unconverted_statement EXCEPTION (-20900, 'SALES.REPAIR_PAYMENT: source statement 1 is an empty SELECT with no select list and no table and was not converted; manual remediation required');
    dup_count NUMBER(38,0) DEFAULT 0;
    duplicate_audit EXCEPTION (-20803, 'Duplicate row in SET table SALES.AUDIT_LOG (EVENT_ID 3, EVENT_TYPE REPAIR)');
BEGIN
    -- Converted: invalid first source statement (an empty SELECT with no select list and no table) -> RAISE unconverted_statement.
    -- Reason: The statement is invalid in Teradata too, so the source procedure could never be created and its repair logic is unknown. Failing closed stops a half-converted repair routine from writing a REPAIR audit row without doing the repair.
    RAISE unconverted_statement;

    -- Converted: Teradata SET-table duplicate-row error 2802 on SALES.AUDIT_LOG -> existence check that raises -20803.
    -- Reason: sales.audit_log is a SET table; EVENT_TYPE is NOT CASESPECIFIC in Teradata mode, so the comparison ignores case and trailing blanks. Runs only after the statement above is replaced.
    SELECT COUNT(*) INTO :dup_count
    FROM SALES.AUDIT_LOG a
    WHERE a.EVENT_ID = 3
      AND UPPER(RTRIM(a.EVENT_TYPE)) = 'REPAIR';
    IF (dup_count > 0) THEN
        RAISE duplicate_audit;
    END IF;

    -- Converted: INSERT INTO sales.audit_log ... VALUES (3, 'REPAIR') -> same insert on SALES.AUDIT_LOG.
    -- Reason: Standard SQL insert; only the name changes per the naming map.
    INSERT INTO SALES.AUDIT_LOG (EVENT_ID, EVENT_TYPE)
    VALUES (3, 'REPAIR');

    RETURN NULL;
END;
$$;
